/*
* Private reference-order helpers adapted from Reference-LAPACK DGEMV at
* commit 2e5d9c1273435fbd953adb294ed603e4789afaba, BLAS/SRC/dgemv.f,
* blob f6defb8c2950028e68ceb23fdf64673e64d2751e. Written 22-October-1986
* by Jack Dongarra (Argonne National Lab.), Jeremy Du Croz and Sven
* Hammarling (NAG Central Office), and Richard Hanson (Sandia National Labs).
* The full upstream BSD license is retained in dpstf2_ndarray.c and NOTICE.
*/
#ifndef STDLIB_LAPACK_BASE_DPSTF2_PANEL_H
#define STDLIB_LAPACK_BASE_DPSTF2_PANEL_H

#include "stdlib/blas/base/dscal.h"
#include "stdlib/blas/base/dswap.h"
#include <stdint.h>

typedef struct dpstf2_view {
	double *data;
	intmax_t stride1;
	intmax_t stride2;
	intmax_t offset;
} dpstf2_view;

// One-based logical cells retain the pinned algorithm's coordinates.
#define DPSTF2_CELL( view, row, column ) ( (view)->data[ (view)->offset+((row)-1)*(view)->stride1+((column)-1)*(view)->stride2 ] )

/**
* Computes a prevalidated active matrix cell's physical element index.
*/
static intmax_t dpstf2_cell_index( const dpstf2_view *a, const intmax_t row, const intmax_t column ) {
	return a->offset+(row-1)*a->stride1+(column-1)*a->stride2;
}

/**
* Swaps logical fragments using the existing guarded DSWAP ndarray adapter.
*
* Zero counts return before index arithmetic or derived pointer formation.
* Singleton increments normalize to one, avoiding casts of unused strides.
*/
static void dpstf2_swap( const intmax_t count, dpstf2_view *a, const intmax_t rowX, const intmax_t columnX, const int axisX, const intmax_t rowY, const intmax_t columnY, const int axisY ) {
	intmax_t offsetX;
	intmax_t offsetY;
	intmax_t strideX;
	intmax_t strideY;

	if ( count <= 0 ) return;
	offsetX = dpstf2_cell_index( a, rowX, columnX );
	offsetY = dpstf2_cell_index( a, rowY, columnY );
	strideX = count == 1 ? 1 : ( axisX == 0 ? a->stride1 : a->stride2 );
	strideY = count == 1 ? 1 : ( axisY == 0 ? a->stride1 : a->stride2 );
	API_SUFFIX(c_dswap_ndarray)( (CBLAS_INT)count, a->data+offsetX, (CBLAS_INT)strideX, 0, a->data+offsetY, (CBLAS_INT)strideY, 0 );
}

/**
* Scales a logical fragment using the existing guarded DSCAL ndarray adapter.
*/
static void dpstf2_scale( const intmax_t count, const double alpha, dpstf2_view *a, const intmax_t row, const intmax_t column, const int axis ) {
	intmax_t offset;
	intmax_t stride;

	if ( count <= 0 ) return;
	offset = dpstf2_cell_index( a, row, column );
	stride = count == 1 ? 1 : ( axis == 0 ? a->stride1 : a->stride2 );
	API_SUFFIX(c_dscal_ndarray)( (CBLAS_INT)count, alpha, a->data+offset, (CBLAS_INT)stride, 0 );
}

/**
* Returns the first logical maximum ordinal, comparing actual candidate values.
*/
static intmax_t dpstf2_first_max( const intmax_t count, const double *x, const intmax_t stride, const intmax_t offset ) {
	intmax_t winner;
	intmax_t i;
	double maximum;
	double value;

	if ( count < 1 ) return -1;
	maximum = x[ offset ];
	winner = 0;
	for ( i = 1; i < count; i++ ) {
		value = x[ offset+i*stride ];
		if ( value > maximum ) {
			maximum = value;
			winner = i;
		}
	}
	return winner;
}

/**
* Performs only the pinned GEMV modes, alpha=-1 and beta=1.
*
* Upper Trans computes each dot before updating its output; lower NoTrans
* performs ascending scaled column additions. Zero coefficients participate.
* Volatile products round multiplication before addition in both modes.
* Source, X and Y logical cells are disjoint within the injective A view.
*/
static void dpstf2_gemv( const LAPACK_UPLO uplo, const intmax_t n, const intmax_t step, dpstf2_view *a ) {
	intmax_t i;
	intmax_t j;
	double temp;
	volatile double product;

	if ( step <= 1 || step >= n ) return;
	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		for ( j = step+1; j <= n; j++ ) {
			temp = 0.0;
			for ( i = 1; i < step; i++ ) {
				product = DPSTF2_CELL( a, i, j )*DPSTF2_CELL( a, i, step );
				temp += product;
			}
			DPSTF2_CELL( a, step, j ) += -temp;
		}
	} else {
		for ( j = 1; j < step; j++ ) {
			temp = -DPSTF2_CELL( a, step, j );
			for ( i = step+1; i <= n; i++ ) {
				product = temp*DPSTF2_CELL( a, i, j );
				DPSTF2_CELL( a, i, step ) += product;
			}
		}
	}
}

#endif // !STDLIB_LAPACK_BASE_DPSTF2_PANEL_H
